import { deflateRawSync } from 'node:zlib';
import { crc32 } from '@ecs/storage';

export interface GeneratedZipMember {
  name: string;
  bytes: Buffer;
  deflate?: boolean;
  method?: number;
  flags?: number;
  declaredSize?: number;
  declaredCrc?: number;
  compressedBytes?: Buffer;
}
/** Generated bytes only: no console-content or archive fixture is checked in. */
export function generatedZip(members: GeneratedZipMember[]): Buffer {
  const locals: Buffer[] = [],
    central: Buffer[] = [];
  let offset = 0;
  for (const member of members) {
    const name = Buffer.from(member.name),
      body =
        member.compressedBytes ?? (member.deflate ? deflateRawSync(member.bytes) : member.bytes);
    const method = member.method ?? (member.deflate ? 8 : 0),
      crc = member.declaredCrc ?? (crc32(member.bytes) ^ 0xffffffff) >>> 0,
      size = member.declaredSize ?? member.bytes.length;
    const local = Buffer.alloc(30 + name.length);
    local.writeUInt32LE(0x04034b50);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(member.flags ?? 0, 6);
    local.writeUInt16LE(method, 8);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(body.length, 18);
    local.writeUInt32LE(size, 22);
    local.writeUInt16LE(name.length, 26);
    name.copy(local, 30);
    locals.push(local, body);
    const record = Buffer.alloc(46 + name.length);
    record.writeUInt32LE(0x02014b50);
    record.writeUInt16LE(20, 4);
    record.writeUInt16LE(20, 6);
    record.writeUInt16LE(member.flags ?? 0, 8);
    record.writeUInt16LE(method, 10);
    record.writeUInt32LE(crc, 16);
    record.writeUInt32LE(body.length, 20);
    record.writeUInt32LE(size, 24);
    record.writeUInt16LE(name.length, 28);
    record.writeUInt32LE(offset, 42);
    name.copy(record, 46);
    central.push(record);
    offset += local.length + body.length;
  }
  const directory = Buffer.concat(central),
    end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50);
  end.writeUInt16LE(members.length, 8);
  end.writeUInt16LE(members.length, 10);
  end.writeUInt32LE(directory.length, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...locals, directory, end]);
}
